package com.xksystem.logistics.tms;
import static org.assertj.core.api.Assertions.*;
import com.xksystem.logistics.tom.closure.*;
import java.nio.charset.StandardCharsets;
import java.io.ByteArrayInputStream;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.util.LinkedMultiValueMap;
import tools.jackson.databind.json.JsonMapper;
class ManagementClosureTest {
 private static byte[] body(String value){return value.getBytes(StandardCharsets.UTF_8);}
 @Test void rawReasonsAndMathematicalTokensHaveExactIndependentHashIdentity(){String raw=" \u0000 e\u0301\r\n合成 \ufeff ";String text=JsonMapper.builder().build().writeValueAsString(raw);var a=ClosureValidation.command(body("{\"expectedVersion\":0,\"reason\":"+text+",\"confirmCompletion\":true}"),true);var b=ClosureValidation.command(body("{\"confirmCompletion\":true,\"reason\":"+text+",\"expectedVersion\":-0.0e0}"),true);assertThat(a.reason()).isEqualTo(raw);assertThat(a.hash()).isEqualTo(b.hash());assertThat(a.hash()).isNotEqualTo(ClosureValidation.command(body("{\"expectedVersion\":0,\"reason\":\"合成\",\"confirmCompletion\":true}"),true).hash());}
 @Test void strictConfirmationIsNotAnOrderTokenOrDigestWaiver(){for(String text:List.of("{}","[]","{} {}","{\"expectedVersion\":0,\"reason\":\"x\",\"confirmClosure\":true}","{\"expectedVersion\":0,\"reason\":\"x\",\"confirmCompletion\":false}","{\"expectedVersion\":0,\"reason\":\"x\",\"reason\":\"y\",\"confirmCompletion\":true}","{\"expectedVersion\":0,\"reason\":\"x\",\"confirmCompletion\":true,\"expectedProofDigest\":\"x\"}"))assertThatThrownBy(()->ClosureValidation.command(body(text),true)).isInstanceOfSatisfying(ClosureFailure.class,e->assertThat(e.code()).isEqualTo("E0400"));assertThatThrownBy(()->ClosureValidation.command(new byte[]{(byte)0xc3,0x28},false)).isInstanceOf(ClosureFailure.class);}
 @Test void rawReasonWhitespaceAndUnicodeBoundsAreNotTrimmedOrNormalized(){for(String blank:List.of(""," \t\n\u001c\u00a0\ufeff"))assertThatThrownBy(()->ClosureValidation.rawReason(blank)).isInstanceOf(ClosureFailure.class);assertThat(ClosureValidation.rawReason("\u0085")).isEqualTo("\u0085");assertThat(ClosureValidation.rawReason("🚚".repeat(1000))).hasSize(2000);for(String invalid:List.of("x".repeat(1001),"\ud800","\udc00"))assertThatThrownBy(()->ClosureValidation.rawReason(invalid)).isInstanceOf(ClosureFailure.class);}
 @Test void versionErrorsExposeExactlyTheirOwnUnit(){assertThat(ClosureFailure.version(1,true).data()).isEqualTo(Map.of("reason","VERSION_CONFLICT","actualConfirmationVersion",1L));assertThat(ClosureFailure.version(3,false).data()).isEqualTo(Map.of("reason","VERSION_CONFLICT","actualOrderVersion",3L));for(String number:List.of("-1","0.1","9007199254740992","1e10000000","null","\"1\""))assertThatThrownBy(()->ClosureValidation.command(body("{\"expectedVersion\":"+number+",\"confirmClosure\":true,\"reason\":\"x\"}"),false)).isInstanceOf(ClosureFailure.class);}
 @Test void boundedActualStreamConsumesOnlyOverflowByte()throws Exception{var input=new ByteArrayInputStream(new byte[ClosureValidation.JSON_CAP+99]);assertThatThrownBy(()->ClosureValidation.bounded(input,-1)).isInstanceOfSatisfying(ClosureFailure.class,e->{assertThat(e.status()).isEqualTo(413);assertThat(e.data()).isNull();});assertThat(input.available()).isEqualTo(98);assertThat(ClosureValidation.bounded(new ByteArrayInputStream(new byte[ClosureValidation.JSON_CAP]),-1)).hasSize(ClosureValidation.JSON_CAP);}
 @Test void managerPagesAreBoundedAndDoNotAcceptIdentityOverrideOrUnapprovedSort(){var query=new LinkedMultiValueMap<String,String>();assertThat(ClosureValidation.query(query,"confirmations").state()).isEqualTo("PENDING");assertThat(ClosureValidation.query(query,"worklist").state()).isEqualTo("OPEN");for(String field:List.of("actorId","customerId","company","sort","q","proofDigest")){query.clear();query.add(field,"x");assertThatThrownBy(()->ClosureValidation.query(query,"worklist")).isInstanceOf(ClosureFailure.class);}query.clear();query.add("page","1");query.add("page","1");assertThatThrownBy(()->ClosureValidation.query(query,"page")).isInstanceOf(ClosureFailure.class);}
 @Test void ownedLedgerCodecRoundTripsRawNulNfdLiteralEscapesAndSupplementaryPairs(){
  var at=java.time.Instant.parse("2026-11-26T12:34:56.123456Z");String reason=" \u0000 e\u0301 🚚 \\u0000 \n ",name="合成e\u0301🚚";
  var actor=new ClosureDtos.Actor("ADMIN",name);var fact=new ClosureDtos.ConfirmationFact(UUID.randomUUID(),1,at,PolicyMode.SYNTHETIC_TEST_ONLY,reason,actor);var confirmation=new ClosureDtos.ConfirmationResult(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),2,1,fact);
  String stored=ManagementReceiptCodec.confirmation(confirmation);var node=JsonMapper.builder().build().readTree(stored);assertThat(node.get("codecVersion").asInt()).isEqualTo(1);assertThat(node.get("confirmation").get("reason").asString()).isEqualTo(Base64.getEncoder().encodeToString(reason.getBytes(StandardCharsets.UTF_8)));assertThat(ManagementReceiptCodec.confirmation(stored)).isEqualTo(confirmation);
  var witness=new ClosureDtos.Witness(UUID.randomUUID(),2,3,at,PolicyMode.SYNTHETIC_TEST_ONLY,true,reason,2,actor);var closure=new ClosureDtos.Result(UUID.randomUUID(),"LG-SYNTHETIC-ORDER","CLOSED","ACCEPTED",3,witness);assertThat(ManagementReceiptCodec.closure(ManagementReceiptCodec.closure(closure))).isEqualTo(closure);
  for(String invalid:List.of("\ud800","\udc00")){var bad=new ClosureDtos.ConfirmationFact(fact.id(),1,at,PolicyMode.SYNTHETIC_TEST_ONLY,invalid,actor);assertThatThrownBy(()->ManagementReceiptCodec.confirmation(new ClosureDtos.ConfirmationResult(confirmation.completionId(),confirmation.assignmentId(),confirmation.taskId(),2,1,bad))).isInstanceOf(ClosureFailure.class);}
 }
 @Test void ownedLedgerCodecRejectsUnknownShapeVersionAndNonCanonicalOrInvalidUtf8Base64(){
  var at=java.time.Instant.parse("2026-11-26T12:34:56.123456Z");var fact=new ClosureDtos.ConfirmationFact(UUID.randomUUID(),1,at,PolicyMode.SYNTHETIC_TEST_ONLY,"a",new ClosureDtos.Actor("ADMIN","合成"));var result=new ClosureDtos.ConfirmationResult(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),2,1,fact);var mapper=JsonMapper.builder().build();String original=ManagementReceiptCodec.confirmation(result);
  for(String bad:List.of("YQ","YQ==\n","YR==","/w==","7aCA","_","\u0000")){var node=(tools.jackson.databind.node.ObjectNode)mapper.readTree(original);((tools.jackson.databind.node.ObjectNode)node.get("confirmation")).put("reason",bad);assertThatThrownBy(()->ManagementReceiptCodec.confirmation(mapper.writeValueAsString(node))).isInstanceOfSatisfying(ClosureFailure.class,e->{assertThat(e.status()).isEqualTo(500);assertThat(e.data()).isNull();assertThat(e.getCause()).isNull();});}
  for(int version:List.of(0,2)){var node=(tools.jackson.databind.node.ObjectNode)mapper.readTree(original);node.put("codecVersion",version);assertThatThrownBy(()->ManagementReceiptCodec.confirmation(mapper.writeValueAsString(node))).isInstanceOf(ClosureFailure.class);}
  var extra=(tools.jackson.databind.node.ObjectNode)mapper.readTree(original);extra.put("unexpected",true);assertThatThrownBy(()->ManagementReceiptCodec.confirmation(mapper.writeValueAsString(extra))).isInstanceOf(ClosureFailure.class);
  assertThatThrownBy(()->ManagementReceiptCodec.confirmation(original.replace("\"codecVersion\":1","\"codecVersion\":1,\"codecVersion\":1"))).isInstanceOf(ClosureFailure.class);
 }
}
